-- Extend only the exact former standard pool after the economy v14 merge.
-- Custom restrictions, prices, names and already issued personal cycles survive.
UPDATE neighbor_settings
SET settings=jsonb_set(settings,'{allowedItemIds}','["berries","wood","stone","ore","fiber","planks","rope","metal_parts","dried_berries","smoked_fish","clay","sand","charcoal","iron_ingot","bricks","glass","hardwood","resin","cloth","beams","tools","reinforced_parts","cut_stone","crumb_bait","worm_bait","glow_bait","firefly_bait","star_bait","grilled_fish","fish_soup","berry_fish","hearty_fish","epic_fish","legendary_fish","strawberries","berry_compote","trail_ration","research_gear","blueberries","currants","blackberries","cranberries","strawberry_compote","blueberry_compote","currant_jelly","blackberry_preserve","cranberry_glaze","spice_bait","dusk_bait","quartz","limestone","ceramic_jar","mortar","glass_bottle","lens","packed_berries","trade_crate","field_kit","stone_tile","bottled_compote","berry_gift","grilled_silverfin","smoked_bream","mooncarp_blueberries","pike_berry_sauce","eel_in_jar","festive_sturgeon"]'::jsonb),
    version=version+1,updated_at=clock_timestamp()
WHERE CASE WHEN jsonb_typeof(settings->'allowedItemIds')='array' THEN
    jsonb_array_length(settings->'allowedItemIds')=48
    AND settings->'allowedItemIds' @> '["berries","wood","stone","ore","fiber","planks","rope","metal_parts","dried_berries","smoked_fish","clay","sand","charcoal","iron_ingot","bricks","glass","hardwood","resin","cloth","beams","tools","reinforced_parts","cut_stone","crumb_bait","worm_bait","glow_bait","firefly_bait","star_bait","grilled_fish","berry_fish","hearty_fish","epic_fish","legendary_fish","strawberries","berry_compote","trail_ration","research_gear","blueberries","currants","blackberries","cranberries","strawberry_compote","blueberry_compote","currant_jelly","blackberry_preserve","cranberry_glaze","spice_bait","dusk_bait"]'::jsonb
    AND settings->'allowedItemIds' <@ '["berries","wood","stone","ore","fiber","planks","rope","metal_parts","dried_berries","smoked_fish","clay","sand","charcoal","iron_ingot","bricks","glass","hardwood","resin","cloth","beams","tools","reinforced_parts","cut_stone","crumb_bait","worm_bait","glow_bait","firefly_bait","star_bait","grilled_fish","berry_fish","hearty_fish","epic_fish","legendary_fish","strawberries","berry_compote","trail_ration","research_gear","blueberries","currants","blackberries","cranberries","strawberry_compote","blueberry_compote","currant_jelly","blackberry_preserve","cranberry_glaze","spice_bait","dusk_bait"]'::jsonb
    ELSE false END;
